#include <vector>
#include <omp.h>
#include <algorithm>

void prefixSum(std::vector<double> const& x, std::vector<double> &output) {
    const std::size_t n = x.size();
    output.resize(n);
    if (n == 0) return;

    int maxThreads = 1;
#pragma omp parallel
    {
#pragma omp single
        { maxThreads = omp_get_num_threads(); }
    }

    const int T = std::max(1, maxThreads);
    std::vector<double> blockSums(static_cast<std::size_t>(T) + 1, 0.0); // blockSums[t+1] = sum of block t

#pragma omp parallel
    {
        const int tid = omp_get_thread_num();
        const int nt  = omp_get_num_threads();

        const std::size_t chunk = (n + static_cast<std::size_t>(nt) - 1) / static_cast<std::size_t>(nt);
        const std::size_t begin = std::min<std::size_t>(n, static_cast<std::size_t>(tid) * chunk);
        const std::size_t end   = std::min<std::size_t>(n, begin + chunk);

        // Local prefix within the block
        double run = 0.0;
        for (std::size_t i = begin; i < end; ++i) {
            run += x[i];
            output[i] = run;
        }

        // One writer per slot (no races)
        blockSums[static_cast<std::size_t>(tid) + 1] = run;

#pragma omp barrier

        // Compute offsets (prefix of block sums) serially
#pragma omp single
        {
            for (int t = 1; t <= nt; ++t) {
                blockSums[static_cast<std::size_t>(t)] += blockSums[static_cast<std::size_t>(t) - 1];
            }
        }

#pragma omp barrier

        const double offset = blockSums[static_cast<std::size_t>(tid)];
        for (std::size_t i = begin; i < end; ++i) {
            output[i] += offset;
        }
    }
}
